#!/usr/bin/env python3
"""Build the Bet design system's generated files from its sources.

    python3 tools/build.py                 # tokens.css, fonts.css, icons/icons.js, gallery.html
    python3 tools/build.py --artifact DIR  # also the Design System artifact's tree under DIR/project/

Sources (edit these): tokens.json, bet.css, bet.js, icons/**/*.svg, mascot/**/*.svg, components/*/README.md and
components/*/example.html, README.md, USING.md.
Generated (never edit by hand): tokens.css, fonts.css, icons/icons.js, gallery.html.

In example.html, these placeholders expand to inline SVG: {{icon:NAME}} a glyph, {{icon:NAME:CLASSES}} with extra
classes, {{tile:NAME}} a tile icon (also {{tile:NAME:CLASSES}}), {{bet}} the octopus ({{bet:CLASSES}}), and
{{friend:NAME}} one of Bet's sea friends. Line 1 of example.html is the card marker:
<!-- @dsCard group="Actions" height=120 -->
"""
import json
import os
import re
import shutil
import sys

HERE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))


def path(*p):
    return os.path.join(HERE, *p)


def read(*p):
    with open(path(*p), encoding='utf-8') as f:
        return f.read()


def write(rel, text):
    full = rel if os.path.isabs(rel) else path(rel)
    os.makedirs(os.path.dirname(full), exist_ok=True)
    with open(full, 'w', encoding='utf-8') as f:
        f.write(text)


# ---------- tokens.css ----------
def css_value(v):
    m = re.fullmatch(r'\{([A-Za-z0-9_.-]+)\}', v) if isinstance(v, str) else None
    return 'var(--%s)' % m.group(1) if m else v


def per_theme(entry, theme):
    v = entry['value']
    if isinstance(v, dict):
        return css_value(v.get(theme, v.get('light')))
    return css_value(v)


def build_tokens(tokens):
    light, dark, fixed = [], [], []
    for t in tokens['color']['tokens']:
        lv, dv = per_theme(t, 'light'), per_theme(t, 'dark')
        if isinstance(t['value'], dict):
            light.append('  --%s: %s;' % (t['name'], lv))
            if dv != lv:
                dark.append('  --%s: %s;' % (t['name'], dv))
        else:
            fixed.append('  --%s: %s;' % (t['name'], lv))
    for t in tokens['shadow']['tokens']:
        lv, dv = per_theme(t, 'light'), per_theme(t, 'dark')
        if isinstance(t['value'], dict):
            light.append('  --%s: %s;' % (t['name'], lv))
            if dv != lv:
                dark.append('  --%s: %s;' % (t['name'], dv))
        else:
            fixed.append('  --%s: %s;' % (t['name'], lv))
    for fam in ('spacing', 'radius', 'weight', 'layout'):
        for t in tokens[fam]['tokens']:
            fixed.append('  --%s: %s;' % (t['name'], t['value']))
    for key, stack in tokens['type']['families'].items():
        fixed.append('  --font-%s: %s;' % (key, stack))
    out = ['/* Bet tokens, generated from tokens.json by tools/build.py. Do not edit by hand. */',
           '/* Theme: data-theme="light" | "dark" on <html>, a shadow host or any element; without it, the system setting. */',
           ':root, :host {']
    out += fixed + light + ['  color-scheme: light;', '}']
    dark_block = dark + ['  color-scheme: dark;']
    out += ['@media (prefers-color-scheme: dark) {',
            '  :root:not([data-theme="light"]), :host(:not([data-theme="light"])) {']
    out += ['  ' + line for line in dark_block] + ['  }', '}']
    out += ['[data-theme="dark"], :host([data-theme="dark"]) {'] + dark_block + ['}']
    out += ['[data-theme="light"]:not(:root), :host([data-theme="light"]) {'] + light + ['  color-scheme: light;', '}', '']
    return '\n'.join(out)


# ---------- fonts.css ----------
LATIN = ('U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, '
         'U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD')
LATIN_EXT = ('U+0100-02BA, U+02BD-02C5, U+02C7-02CC, U+02CE-02D7, U+02DD-02FF, U+0304, U+0308, U+0329, '
             'U+1D00-1DBF, U+1E00-1E9F, U+1EF2-1EFF, U+2020, U+20A0-20AB, U+20AD-20C4, U+2113, U+2C60-2C7F, U+A720-A7FF')


def build_fonts():
    out = ['/* Bet fonts, generated by tools/build.py. Variable fonts from Google Fonts (SIL Open Font License):',
           '   one file per family and subset covers weights 400 to 700. Use this where Google Fonts cannot load',
           '   (extension pages, offline). Pages that can reach Google Fonts may link it instead:',
           '   https://fonts.googleapis.com/css2?family=Google+Sans+Flex:wght@400;500;700&family=Roboto:wght@400;500;700&display=swap */']
    for fam, slug in (('Google Sans Flex', 'GoogleSansFlex'), ('Roboto', 'Roboto')):
        for sub, rng in (('latin-ext', LATIN_EXT), ('latin', LATIN)):
            out.append("@font-face {\n  font-family: '%s';\n  font-style: normal;\n  font-weight: 400 700;\n"
                       "  font-display: swap;\n  src: url('fonts/%s-%s.woff2') format('woff2');\n  unicode-range: %s;\n}"
                       % (fam, slug, sub, rng))
    return '\n'.join(out) + '\n'


# ---------- icons.js ----------
def svg_files(folder):
    full = path(folder)
    if not os.path.isdir(full):
        return {}
    return {f[:-4]: read(folder, f).strip() for f in sorted(os.listdir(full)) if f.endswith('.svg')}


def build_icons():
    data = {
        'glyph': svg_files('icons/glyph'),
        'tile': svg_files('icons/tile'),
        'mascot': svg_files('mascot'),
        'friends': svg_files('mascot/friends'),
    }
    body = json.dumps(data, indent=2, ensure_ascii=False)
    return ('/* Bet pixel art as markup, generated from icons/ and mascot/ by tools/build.py. Do not edit by hand.\n'
            '   window.BetIcons = { glyph, tile, mascot, friends }. Bet.icon(name) and Bet.mascot() read it. */\n'
            '(function (root) {\n  root.BetIcons = ' + body.replace('\n', '\n  ') + ';\n'
            '})(typeof window !== "undefined" ? window : this);\n'), data


# ---------- examples ----------
def expand(html, icons):
    def one(kind, name, cls):
        if kind == 'bet':
            svg = icons['mascot']['bet']
            return svg.replace('class="bet"', 'class="bet %s"' % cls, 1) if cls else svg
        if kind == 'friend':
            return icons['friends'][name]
        svg = icons['glyph' if kind == 'icon' else 'tile'][name]
        if cls:
            svg = re.sub(r'class="(bet-pxi|bet-pi)"', r'class="\1 %s"' % cls, svg, count=1)
        return svg

    out = re.sub(r'\{\{(icon|tile|friend):([A-Za-z0-9-]+)(?::([^}]+))?\}\}',
                 lambda m: one(m.group(1), m.group(2), m.group(3)), html)
    out = re.sub(r'\{\{bet(?::([^}]+))?\}\}', lambda m: one('bet', None, m.group(1)), out)
    left = re.findall(r'\{\{[^}]*\}\}', out)
    if left:
        raise SystemExit('unknown placeholder(s): %s' % ', '.join(sorted(set(left))))
    return out


def components():
    root = path('components')
    items = []
    for name in sorted(os.listdir(root)):
        d = os.path.join(root, name)
        if not os.path.isdir(d):
            continue
        ex = os.path.join(d, 'example.html')
        if not os.path.exists(ex):
            continue
        src = open(ex, encoding='utf-8').read()
        marker = src.split('\n', 1)[0]
        m = re.match(r'<!-- @dsCard (.*?)-->', marker)
        if not m:
            raise SystemExit('%s: line 1 must be the @dsCard marker' % ex)
        group = re.search(r'group="([^"]+)"', m.group(1))
        order = re.search(r'order=(\d+)', m.group(1))
        items.append({'name': name, 'src': src, 'group': group.group(1) if group else 'Other',
                      'order': int(order.group(1)) if order else 50, 'gallery_only': 'gallery-only' in m.group(1)})
    return items


GROUPS = ['Foundations', 'Actions', 'Navigation', 'Surfaces', 'Forms', 'Content', 'Bet', 'Pixel art', 'Feedback', 'Motion']


def build_gallery(items, icons):
    def gkey(it):
        return (GROUPS.index(it['group']) if it['group'] in GROUPS else 99, it['order'], it['name'])

    sections, nav = [], []
    group = None
    for it in sorted(items, key=gkey):
        if it['group'] != group:
            group = it['group']
            sections.append('<h2 class="g-group" id="g-%s">%s</h2>' % (re.sub(r'\W+', '-', group.lower()), group))
            nav.append('<a href="#g-%s">%s</a>' % (re.sub(r'\W+', '-', group.lower()), group))
        body = expand(it['src'].split('\n', 1)[1], icons)
        sections.append('<section class="g-card" id="c-%s"><h3 class="g-name">%s</h3><div class="g-stage">%s</div></section>'
                        % (it['name'], it['name'], body))
    return GALLERY.replace('{{NAV}}', ''.join(nav)).replace('{{SECTIONS}}', '\n'.join(sections))


GALLERY = '''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<title>Bet design system</title>
<!-- Generated by tools/build.py from components/*/example.html. Open it from this folder; do not edit. -->
<script src="bet-theme-head.js"></script>
<link rel="stylesheet" href="fonts.css">
<link rel="stylesheet" href="tokens.css">
<link rel="stylesheet" href="bet.css">
<script src="icons/icons.js"></script>
<script src="bet.js" data-bet-init></script>
<style>
  body { margin: 0; background: var(--bg); }
  .g-top { position: sticky; top: 0; z-index: 30; display: flex; align-items: center; justify-content: space-between; gap: 16px;
           padding: 12px max(16px, env(safe-area-inset-left, 0px)); background: color-mix(in srgb, var(--bg) 86%, transparent);
           -webkit-backdrop-filter: blur(12px); backdrop-filter: blur(12px); }
  .g-top nav { display: flex; flex-wrap: wrap; gap: 4px 14px; font-size: 0.86rem; }
  .g-top nav a { color: var(--muted); font-weight: 500; }
  .g-wrap { max-width: 1100px; margin: 0 auto; padding: 24px max(16px, env(safe-area-inset-left, 0px)) 96px; display: grid; gap: 20px; }
  .g-group { margin: 36px 0 0; font-family: var(--font-display); font-weight: 500; font-size: 2rem; letter-spacing: -0.04em; color: var(--ink); }
  .g-card { display: grid; gap: 14px; min-width: 0; }
  .g-name { margin: 0; font-family: var(--font-display); font-weight: 500; font-size: 0.95rem; color: var(--muted); }
  .g-stage { min-width: 0; padding: 28px; border-radius: 24px; background: var(--bg); box-shadow: inset 0 0 0 1.5px var(--tile-line); overflow: hidden; }
  @media (max-width: 600px) { .g-stage { padding: 18px; } }
</style>
</head>
<body class="bet-base">
<header class="g-top"><span class="bet-says">{{BET}}<b class="bet-wordmark">bet</b><span class="bet-caption">design system</span></span>
<nav>{{NAV}}</nav>
<button class="bet-icon-btn bet-theme-toggle" type="button" aria-label="Switch theme">{{SUN}}{{MOON}}</button></header>
<main class="g-wrap">
{{SECTIONS}}
</main>
</body>
</html>
'''


# ---------- artifact tree ----------
def build_artifact_tokens_css(tokens):
    """The first tokens.css for the Design System artifact, laid out as its page compiles one (themes as
    [data-theme] blocks, type styles as classes, @font-face per font). The page takes it over on its first save."""
    first = tokens['color']['themes'][0]['id']
    out = ['/* Bet, generated from tokens.json */']
    for th in tokens['color']['themes']:
        sel = ':root, [data-theme="%s"]' % th['id'] if th['id'] == first else '[data-theme="%s"]' % th['id']
        lines = []
        for fam in ('color', 'shadow'):
            for t in tokens[fam]['tokens']:
                v = per_theme(t, th['id'])
                if th['id'] == first or isinstance(t['value'], dict) or v.startswith('var('):
                    lines.append('  --%s: %s;' % (t['name'], v))
        out += [sel + ' {'] + lines + ['}']
    rest = []
    for fam in ('spacing', 'radius', 'weight', 'layout'):
        for t in tokens[fam]['tokens']:
            rest.append('  --%s: %s;' % (t['name'], t['value']))
    for key, stack in tokens['type']['families'].items():
        rest.append('  --font-%s: %s;' % (key, stack))
    out += [':root {'] + rest + ['}']
    for g in tokens['type']['groups']:
        for st in g['styles']:
            out.append('.%s { font-family: var(--font-%s); font-size: %s; line-height: %s; font-weight: %s; letter-spacing: %s; }'
                       % (st['name'], st.get('family', g['family']), st['fontSize'], st['lineHeight'], st['fontWeight'], st.get('letterSpacing', 'normal')))
    for f in tokens['type']['fonts']:
        out.append("@font-face { font-family: '%s'; src: url('%s') format('woff2'); font-weight: %s; font-style: %s; font-display: swap; }"
                   % (f['family'], f['file'], f['weight'], f.get('style', 'normal')))
    return '\n'.join(out) + '\n'


def build_artifact(out, items, icons, tokens):
    proj = os.path.join(out, 'project')
    if os.path.isdir(proj):
        shutil.rmtree(proj)
    os.makedirs(proj)
    for f in ('README.md', 'USING.md', 'tokens.json'):
        shutil.copy(path(f), os.path.join(proj, f))
    write(os.path.join(proj, 'tokens.css'), build_artifact_tokens_css(tokens))
    os.makedirs(os.path.join(proj, 'fonts'))
    for f in tokens['type']['fonts']:
        shutil.copy(path(f['file']), os.path.join(proj, f['file']))
    css = read('bet.css')
    js = read('icons', 'icons.js') + '\n' + read('bet.js')
    for bad in ('</script', '<!--'):
        if bad in js.lower():
            raise SystemExit('bundle.js would contain %s' % bad)
    if '</style' in css.lower():
        raise SystemExit('bundle.css would contain </style')
    write(os.path.join(proj, 'components', 'bundle.css'), css)
    write(os.path.join(proj, 'components', 'bundle.js'), js)
    for it in items:
        if it['gallery_only']:
            continue
        d = os.path.join(proj, 'components', it['name'])
        marker, body = it['src'].split('\n', 1)
        marker = re.sub(r'\s*(order=\d+|gallery-only)', '', marker)
        script = '\n<script>Bet.init(document);</script>\n' if 'Bet.init' not in body else ''
        write(os.path.join(d, 'preview.html'), marker + '\n' + expand(body, icons).rstrip() + script)
        readme = path('components', it['name'], 'README.md')
        if os.path.exists(readme):
            shutil.copy(readme, os.path.join(d, 'README.md'))
    cover = path('components', 'Cover', 'preview.html')
    if os.path.exists(cover):
        write(os.path.join(proj, 'components', 'Cover', 'preview.html'), read('components', 'Cover', 'preview.html'))
    return proj


THEME_HEAD = ('/* Sets data-theme before first paint: the saved choice ("bet-theme"), else the system setting. Load it in <head>\n'
              '   with a plain <script src>, before any stylesheet. Not for claude.ai artifacts (the host sets data-theme). */\n'
              '(function(){var t=null;try{t=localStorage.getItem("bet-theme")}catch(e){}'
              'if(t!=="light"&&t!=="dark")t=window.matchMedia&&matchMedia("(prefers-color-scheme: dark)").matches?"dark":"light";'
              'document.documentElement.setAttribute("data-theme",t)})();\n')


def build_css_js(tokens_css, fonts_css):
    """bet-css.js: the stylesheets as strings, for UI inside a shadow root in a content script (no file fetches,
    no web_accessible_resources needed for the CSS). Bet.fontFaces(base) returns the @font-face rules pointed at
    the extension's copy of fonts/ (a document-level <style>; Chrome ignores @font-face inside a shadow root)."""
    faces = re.sub(r"url\('fonts/", "url('{{BASE}}", fonts_css.split('*/', 1)[1]).strip()
    return ('/* Generated by tools/build.py from tokens.css and bet.css. Do not edit by hand.\n'
            '   window.BetCSS: tokens + components as one string, for a shadow root.\n'
            '   window.BetFontFaces(baseUrl): @font-face rules for the document, baseUrl ending in fonts/. */\n'
            '(function (root) {\n'
            '  root.BetCSS = ' + json.dumps(tokens_css + '\n' + read('bet.css')) + ';\n'
            '  var faces = ' + json.dumps(faces) + ';\n'
            '  root.BetFontFaces = function (base) { return faces.split("{{BASE}}").join(base); };\n'
            '})(typeof window !== "undefined" ? window : this);\n')


def main():
    tokens = json.loads(read('tokens.json'))
    tokens_css = build_tokens(tokens)
    fonts_css = build_fonts()
    write('tokens.css', tokens_css)
    write('fonts.css', fonts_css)
    write('bet-css.js', build_css_js(tokens_css, fonts_css))
    write('bet-theme-head.js', THEME_HEAD)
    js, icons = build_icons()
    write('icons/icons.js', js)
    items = components()
    page = build_gallery(items, icons)
    page = page.replace('{{BET}}', icons['mascot']['bet'].replace('class="bet"', 'class="bet bet-32"', 1))
    page = page.replace('{{SUN}}', icons['glyph']['sun'].replace('class="bet-pxi"', 'class="bet-pxi i-sun is-drawn"', 1))
    page = page.replace('{{MOON}}', icons['glyph']['moon'].replace('class="bet-pxi"', 'class="bet-pxi i-moon is-drawn"', 1))
    write('gallery.html', page)
    print('built tokens.css, fonts.css, bet-theme-head.js, icons/icons.js (%d glyphs, %d tiles), gallery.html (%d components)'
          % (len(icons['glyph']), len(icons['tile']), len(items)))
    if '--artifact' in sys.argv:
        out = sys.argv[sys.argv.index('--artifact') + 1]
        proj = build_artifact(out, items, icons, tokens)
        print('artifact tree in', proj)


if __name__ == '__main__':
    main()
